use std::println;

use slint::ComponentHandle;
use vexide::{math::Angle, prelude::*};
use vexide_motorgroup::MotorGroup;

mod curves;

struct Robot {
    controller: Controller,
    left_motors: MotorGroup,
    right_motors: MotorGroup,
    imu: InertialSensor,
    claw_motor: Motor,
    claw_tilt: Motor,
    lift_motors: MotorGroup,
    ui: App,
    intake_motor: Motor
}

// Include the modules generated by Slint for your UI files.
// You will need to configure your `build.rs` to do this; see below.
slint::include_modules!();


impl Compete for Robot {
    async fn autonomous(&mut self) {
        println!("Autonomous!");
        loop {
            sleep(Controller::UPDATE_INTERVAL).await; 
        }
    }

    async fn driver(&mut self) {
        println!("Driver!");
        let mut claw_rot_state: f64 = 0.0;
        loop {
            let state = self.controller.state().unwrap_or_default();

            // CONTROLS
            let c_turn:     f64 = state.right_stick.x();
            let c_throttle: f64 = state.left_stick.y();

            let c_lift:     f64 = if state.button_l1.is_pressed() { 1.0 }  // Up
                             else if state.button_l2.is_pressed() {-1.0 }  // Down
                             else                                 { 0.0 }; // Hold

            let c_intake:   f64 = if state.button_r1.is_pressed() { 1.0 }  // Intake
                             else if state.button_r2.is_pressed() {-1.0 }  // Outtake
                             else                                 { 0.0 }; // Hold

            let c_claw:     f64 = if state.button_r1.is_pressed() { 1.0 }  // Intake
                             else if state.button_r2.is_pressed() {-1.0 }  // Outtake
                             else                                 { 0.0 }; // Hold

            let c_claw_rot: f64 = if state.button_a. is_pressed() { 1.0 }  // Up
                             else if state.button_b. is_pressed() { 0.1 }  // Down
                             else                                 {-1.0 }; // Hold

            // DRIVING
            let l = c_throttle + curves::steering(c_turn) * curves::turn_speed(c_turn);
            let r = c_throttle - curves::steering(c_turn) * curves::turn_speed(c_turn);

            _ = self.left_motors.set_voltage(l * self.left_motors.max_voltage() * 0.8);
            _ = self.right_motors.set_voltage(r * self.left_motors.max_voltage() * 0.8);

            // LIFT
            _ = self.lift_motors.set_voltage(c_lift * self.lift_motors.max_voltage());

            // INTAKE
            _ = self.intake_motor.set_voltage(-c_intake * self.lift_motors.max_voltage());

            // CLAW
            _ = self.claw_motor.set_voltage(-c_claw * self.lift_motors.max_voltage());

            // CLAW ROTATION
            if c_claw_rot != -1.0 { claw_rot_state = c_claw_rot }
            _ = self.claw_tilt.set_position_target(Angle::from_degrees(claw_rot_state * 120.0), 200);

            sleep(Controller::UPDATE_INTERVAL).await; 
        }
    }
}

#[vexide::main(banner(enabled = false))]
async fn main(peripherals: vexide::prelude::Peripherals) {
    let controller = peripherals.primary_controller;

    let left_motors = MotorGroup::new(vec![
        Motor::new(peripherals.port_8, Gearset::Green, Direction::Reverse),
        Motor::new(peripherals.port_15, Gearset::Green, Direction::Reverse)
    ]);
    let right_motors = MotorGroup::new(vec![
        Motor::new(peripherals.port_18, Gearset::Green, Direction::Forward),
        Motor::new(peripherals.port_13, Gearset::Green, Direction::Forward)
    ]);

    let mut imu = InertialSensor::new(peripherals.port_1);
    _ = imu.calibrate().await;

    let lift_motors = MotorGroup::new(vec![
        Motor::new(peripherals.port_2, Gearset::Green, Direction::Forward),
        Motor::new(peripherals.port_6, Gearset::Green, Direction::Reverse)
    ]);
    let claw_motor = Motor::new_exp(peripherals.port_5, Direction::Forward);
    let claw_tilt = Motor::new_exp(peripherals.port_4, Direction::Forward);
    let intake_motor = Motor::new(peripherals.port_10, Gearset::Green, Direction::Forward);

    // Initialize the Slint platform with the V5 display-backed implementation.
    vexide_slint::initialize_slint_platform(peripherals.display);
    let ui: App = App::new()
        .expect("Failed to create application");

    let robot = Robot {
        controller,
        left_motors,
        right_motors,
        imu,
        claw_motor,
        claw_tilt,
        lift_motors,
        ui: ui.clone_strong(),
        intake_motor
    };

    // Run vex code in a seperate thread
    vexide::task::spawn(robot.compete()).detach();

    ui.run().expect("Failed to run application");

}